def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The top-row color sequence defines beam origins; matching edge markers
    # extend beams inward along their row, while top markers extend down columns.
    top = {c: grid[0][c] for c in range(w) if grid[0][c] != 0}
    for c, color in top.items():
        if color == 0:
            continue
        for r in range(h):
            if r == 0 or grid[r][c] == color:
                out[r][c] = color
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or r == 0:
                continue
            if c == 0 and color in top.values():
                origin = next((x for x, v in top.items() if v == color), None)
                if origin is not None:
                    for x in range(min(c, origin), max(c, origin) + 1):
                        out[r][x] = color
            elif c == w - 1 and color in top.values():
                origin = next((x for x, v in top.items() if v == color), None)
                if origin is not None:
                    for x in range(min(c, origin), max(c, origin) + 1):
                        out[r][x] = color
    return out
