def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    top = {c: grid[0][c] for c in range(w) if grid[0][c]}
    # Continue each color in the top pattern vertically through the grid.
    for c, color in top.items():
        for r in range(h):
            out[r][c] = color
    # Same-colored markers on the left/right edges connect horizontally
    # to the column where that color appears in the top pattern.
    for r in range(1, h):
        if grid[r][0] in top.values() and grid[r][0] != 0:
            color = grid[r][0]
            c = next(c for c, v in top.items() if v == color)
            for x in range(0, c + 1):
                out[r][x] = color
        if grid[r][w - 1] in top.values() and grid[r][w - 1] != 0:
            color = grid[r][w - 1]
            c = next(c for c, v in top.items() if v == color)
            for x in range(c, w):
                out[r][x] = color
    return out
