def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    top_cols = {grid[0][c]: c for c in range(w) if grid[0][c] != 0}
    stops = {}
    for r in range(1, h):
        for c in (0, w - 1):
            color = grid[r][c]
            if color in top_cols:
                stops.setdefault(color, r)
                target = top_cols[color]
                lo, hi = sorted((c, target))
                for x in range(lo, hi + 1):
                    out[r][x] = color
    # Each top-row color forms a vertical ray, ending at its matching
    # boundary marker if present; otherwise it continues to the bottom.
    for color, c in top_cols.items():
        end = stops.get(color, h - 1)
        for r in range(1, end + 1):
            out[r][c] = color
    return out
